{
  blocked(x,y){ for(const t of trees){const dx=x-t.x,dy=y-t.y,rr=t.r+0.5; if(dx*dx+dy*dy<rr*rr)return true;}
    for(const b of buildings){if(Math.abs(x-b.x)<b.w/2+0.45&&Math.abs(y-b.y)<b.h/2+0.45)return true;} return false; },
  losBlocked(x1,y1,x2,y2){ return treeBlocks(x1,y1,x2,y2); },
  coverAt(x,y){ return concealed({x,y}); },
  push(c,u,dt){
    if(trees.length)for(const t of trees){const dx=u.x-t.x,dy=u.y-t.y,d2=dx*dx+dy*dy,rr=t.r+0.5; if(d2<rr*rr&&d2>1e-4){const d=Math.sqrt(d2);u.x=t.x+dx/d*rr;u.y=t.y+dy/d*rr;}}
    if(buildings.length)for(const b of buildings){const dx=u.x-b.x,dy=u.y-b.y,hx=b.w/2+0.45,hy=b.h/2+0.45; if(Math.abs(dx)<hx&&Math.abs(dy)<hy){const ox=hx-Math.abs(dx),oy=hy-Math.abs(dy);
      const gx=(u.tgt&&u.tgt.hp>0)?u.tgt.x:u.x, gy=(u.tgt&&u.tgt.hp>0)?u.tgt.y:u.y;
      if(ox<oy){u.x=b.x+(dx<0?-hx:hx); u.y+=Math.sign(gy-u.y||1)*Math.min(2.6*dt,hy+0.2);}
      else {u.y=b.y+(dy<0?-hy:hy); u.x+=Math.sign(gx-u.x||1)*Math.min(2.6*dt,hx+0.2);}}}
  },
}

